def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    desperate_bids = []
    rich_alive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > DAILY_SALARY * 2:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0)
                prev_bids.append(bid)
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    desperate_bids.append(bid)

    if not alive_opponents:
        base = DAILY_SALARY * 0.28
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(min(budget, max(0.0, base)))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.05:
        scarcity = 2
    elif units <= 1.45:
        scarcity = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    desperate_prev = max(desperate_bids) if desperate_bids else highest_prev

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if urgent:
        target = max(DAILY_SALARY * 0.92, desperate_prev + 2.0)
        if scarcity == 2:
            target = max(target, DAILY_SALARY * 1.02)
        return float(min(budget, target))

    if scarcity == 2:
        if pressured:
            target = max(DAILY_SALARY * 0.86, highest_prev + 1.5)
        else:
            if highest_prev >= DAILY_SALARY * 1.4:
                target = DAILY_SALARY * 0.34
            else:
                target = max(DAILY_SALARY * 0.58, highest_prev + 1.0)
    elif scarcity == 1:
        if pressured:
            target = max(DAILY_SALARY * 0.72, highest_prev + 1.0)
        else:
            if highest_prev >= DAILY_SALARY * 1.2:
                target = DAILY_SALARY * 0.30
            else:
                target = max(DAILY_SALARY * 0.46, highest_prev * 0.88)
    else:
        if pressured:
            target = max(DAILY_SALARY * 0.56, highest_prev * 0.82)
        else:
            target = DAILY_SALARY * 0.24
            if rich_alive >= 1 and highest_prev < DAILY_SALARY * 0.5:
                target = DAILY_SALARY * 0.29

    if budget < DAILY_SALARY * 1.2 and not pressured:
        target = min(target, DAILY_SALARY * 0.35)

    target = max(0.0, target)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQUIREMENT = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return max(1.0, min(my_current_budget, DAILY_SALARY * 0.1))

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    my_bid = 0.0
    if my_current_hp <= 2:
        my_bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 4:
        my_bid = DAILY_SALARY * 0.8
    else:
        my_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        water_per_participant = current_supply / (num_alive_opponents + 1)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_current_hp > 3:
                if water_per_participant >= WATER_REQUIREMENT * 1.5:
                    my_bid = min(my_bid, highest_prev_bid * 0.9)
                else:
                    my_bid = max(my_bid, highest_prev_bid + 2.0)
            else:
                my_bid = max(my_bid, highest_prev_bid + 5.0)
        else:
            if water_per_participant < WATER_REQUIREMENT * 1.2:
                my_bid = max(my_bid, highest_prev_bid + 5.0)
            else:
                my_bid = max(my_bid, highest_prev_bid + 1.0)
                my_bid = min(my_bid, DAILY_SALARY * 0.6)

    my_bid = max(my_bid, DAILY_SALARY * 0.2)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_current_hp > 0:
        my_bid = max(my_bid, DAILY_SALARY * 0.85)
    elif remaining_days <= 4 and my_current_hp <= 2:
        my_bid = max(my_bid, DAILY_SALARY * 0.99)

    my_bid = min(my_current_budget, my_bid)

    my_bid = max(1.0, my_bid)

    return my_bid

